var cosa,sina,tana,Rsa,Raa,Hs,Ha;
var p2y,p3y,p4y,p5y,al,ea;

var slope;
slope = 14;

ea = 0.5*db.EA;
tana = slope/100;
al = atan(tana);
cosa = cos(al);
sina = sin(al);
Rsa = db.RS*(1-sina);
Raa = db.RA*(1-sina);
Hs = (0.25*db.B-Rsa)*tana;
Ha = (0.25*db.B-ea-Raa)*tana;

p3y = db.ES-Hs;
p2y = p3y-(db.RS*cosa);
p4y = db.ES+Ha;
p5y = p4y+(db.RA*cosa);

StartContour(-db.VPY,-db.VPZ);
 LineTo(db.VY,-db.VPZ);
 LineTo(db.VY,-db.VPZ+p2y);
 ArcTo(db.VY-Rsa,-db.VPZ+p3y,-db.RS,CCW);
