{
  slope = 8;
}
else
{
  slope = 5;
}

tana = slope/100;
al = atan(tana);
cosa = cos(al);
sina = sin(al);
Rsa = db.RS*(1-sina);
Raa = db.RA*(1-sina);
Hs = (0.5*db.B-Rsa)*tana;
Ha = (0.5*db.B-db.EA-Raa)*tana;

